pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    function testFuzz_property(address from, address to) public {
        RecordingReceiver r = new RecordingReceiver();
        address[] memory tos = new address[](2);
        tos[0] = to;
        tos[1] = to;
        uint256 v = 1;

        bool ok = c.transfer(from, address(r), tos, v);
        assertTrue(ok && r.callCount() == tos.length && r.froms(0) == from && r.froms(1) == from && r.tos(0) == tos[0] && r.tos(1) == tos[1] && r.values(0) == v && r.values(1) == v);
    }
}

contract RecordingReceiver {
    uint256 public callCount;
    mapping(uint256 => address) public froms;
    mapping(uint256 => address) public tos;
    mapping(uint256 => uint256) public values;

    function transferFrom(address from, address to, uint256 value) external payable {
        froms[callCount] = from;
        tos[callCount] = to;
        values[callCount] = value;
        callCount++;
    }

    receive() external payable {}
}
